// ***************
// Filename: vision_system_regs.sv
// Author: FPGA Cores 4 U
// Description: Register map of vision_system: its AXI4-Lite register slave
//   (axi4_lite_slave front end) with every register of the block, the ID
//   block first; the registers go to vision_system's logic on named ports,
//   its status comes back on input ports. Lens distortion correction:
//   control, status, image size, distortion coefficients, calibration, model
//   select, homography. Generated by ip/scripts/regmap_gen.py from
//   vision_system_regs.json: edit the JSON and regenerate (the IP_VERSION /
//   IP_DATE stamps are kept).
//   Register map (ADDR_W = 8, byte offsets):
//     0x00 ID          RO   "VSYS" IP identifier, 4 ASCII characters (first
//                       in [31:24])
//     0x04 VERSION     RO   version, ASCII "d.dd" (+0.01 at every source
//                       update)
//     0x08 DATE        RO   date of the last source update, BCD mm/dd/yyyy
//                       (0xMMDDYYYY)
//     0x0C reserved    RO   0
//     0x10 CTRL        WO   [0] soft reset request (self clearing, not
//                       stored)
//     0x14 STATUS      CMD  [0] busy [1] frame done (W1C) [2] reciprocal busy
//     0x18 IMG_WIDTH   RW   active frame width, 1..MAX_W, reset 0x40
//     0x1C IMG_HEIGHT  RW   active frame height, 1..MAX_H, reset 0x40
//     0x20 K1          RW   signed Q16.16 radial coefficient (r^2 term),
//                       reset 0x0
//     0x24 K2          RW   signed Q16.16 radial coefficient (r^4 term),
//                       reset 0x0
//     0x28 K3          RW   signed Q16.16 radial coefficient (r^6 term),
//                       reset 0x0
//     0x2C CENTER_X    RW   unsigned Q16.16, fraction of the width (0.5 =
//                       0x8000), reset 0x8000
//     0x30 CENTER_Y    RW   unsigned Q16.16, fraction of the height, reset
//                       0x8000
//     0x34 SCALE       RW   unsigned Q16.16 edge-crop zoom (1.0 = 0x10000),
//                       reset 0x10000
//     0x38 BYPASS      RW   [0] 1: frames pass unchanged (reset: no
//                       correction until software enables it); taken between
//                       frames, reset 0x1
//     0x3C INTERP_MODE RW   [0] 0 bilinear, 1 bicubic (change only while
//                       idle), reset 0x0
//     0x40 CALIB_MODE  RW   [0] 1 = direct camera calibration (FX / FY / CX /
//                       CY), reset 0x0
//     0x44 FX          RW   signed Q16.16 pixels, focal length x (CALIB_MODE
//                       1), reset 0x10000
//     0x48 FY          RW   signed Q16.16 pixels, focal length y (CALIB_MODE
//                       1), reset 0x10000
//     0x4C CX          RW   signed Q16.16 pixels, principal point x
//                       (CALIB_MODE 1), reset 0x0
//     0x50 CY          RW   signed Q16.16 pixels, principal point y
//                       (CALIB_MODE 1), reset 0x0
//     0x54 P1          RW   signed Q16.16 tangential coefficient 1 (RADIAL),
//                       reset 0x0
//     0x58 P2          RW   signed Q16.16 tangential coefficient 2 (RADIAL),
//                       reset 0x0
//     0x5C MODEL_SEL   RW   [2:0] 0 radial, 1 fisheye (division model), 2
//                       affine (reserved), 3 perspective, 4 scaling
//                       (reserved), 5 panoramic, 6 / 7 reserved; the reserved
//                       codes give the pinhole round trip (near identity) -
//                       software must not select them, reset 0x0
//     0x60 H11         RW   homography, Q16.16, reset 0x10000
//     0x64 H12         RW   homography, Q16.16, reset 0x0
//     0x68 H13         RW   homography translation, pixels, reset 0x0
//     0x6C H21         RW   homography, Q16.16, reset 0x0
//     0x70 H22         RW   homography, Q16.16, reset 0x10000
//     0x74 H23         RW   homography translation, pixels, reset 0x0
//     0x78 H31         RW   homography, Q16.16, reset 0x0
//     0x7C H32         RW   homography, Q16.16, reset 0x0
//   Access: RW read / write (byte strobes), RO read only (writes answer
//   SLVERR), W1C hardware sets / software writes 1 to clear (a set wins), W1S
//   software writes 1 to set / hardware clears, WO write only (reads 0), CMD
//   reads the hardware value, a write gives a pulse with its data. Unmapped
//   words read 0 and ignore writes; above the map: DECERR. Clock - clk. Reset
//   - synchronous active low rst_n. Latency - 2 clocks per write and read.
// Date: 2026-10-21
module vision_system_regs (
  input  logic          clk,              // clock
  input  logic          rst_n,            // synchronous reset, active low
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  axil_if.slave s_axil,
  // r: vision_system_regs_if.regs (src/include/vision_system_regs_if.sv) {ctrl_o=cfg_ctrl ctrl_wr_o=cfg_ctrl_wr status_i=sts_status status_o=cfg_status status_wr_o=cfg_status_wr img_width_o=cfg_img_width img_width_wr_o=cfg_img_width_wr img_height_o=cfg_img_height img_height_wr_o=cfg_img_height_wr k1_o=cfg_k1 k1_wr_o=cfg_k1_wr k2_o=cfg_k2 k2_wr_o=cfg_k2_wr k3_o=cfg_k3 k3_wr_o=cfg_k3_wr center_x_o=cfg_center_x center_x_wr_o=cfg_center_x_wr center_y_o=cfg_center_y center_y_wr_o=cfg_center_y_wr scale_o=cfg_scale scale_wr_o=cfg_scale_wr bypass_o=cfg_bypass bypass_wr_o=cfg_bypass_wr interp_mode_o=cfg_interp_mode interp_mode_wr_o=cfg_interp_mode_wr calib_mode_o=cfg_calib_mode calib_mode_wr_o=cfg_calib_mode_wr fx_o=cfg_fx fx_wr_o=cfg_fx_wr fy_o=cfg_fy fy_wr_o=cfg_fy_wr cx_o=cfg_cx cx_wr_o=cfg_cx_wr cy_o=cfg_cy cy_wr_o=cfg_cy_wr p1_o=cfg_p1 p1_wr_o=cfg_p1_wr p2_o=cfg_p2 p2_wr_o=cfg_p2_wr model_sel_o=cfg_model_sel model_sel_wr_o=cfg_model_sel_wr h11_o=cfg_h11 h11_wr_o=cfg_h11_wr h12_o=cfg_h12 h12_wr_o=cfg_h12_wr h13_o=cfg_h13 h13_wr_o=cfg_h13_wr h21_o=cfg_h21 h21_wr_o=cfg_h21_wr h22_o=cfg_h22 h22_wr_o=cfg_h22_wr h23_o=cfg_h23 h23_wr_o=cfg_h23_wr h31_o=cfg_h31 h31_wr_o=cfg_h31_wr h32_o=cfg_h32 h32_wr_o=cfg_h32_wr}
  vision_system_regs_if.regs r
);
  // register signals, joined to the interface r
  logic ctrl_o;
  logic ctrl_wr_o;
  logic [3-1:0] status_i;
  logic [3-1:0] status_o;
  logic status_wr_o;
  logic [32-1:0] img_width_o;
  logic img_width_wr_o;
  logic [32-1:0] img_height_o;
  logic img_height_wr_o;
  logic [32-1:0] k1_o;
  logic k1_wr_o;
  logic [32-1:0] k2_o;
  logic k2_wr_o;
  logic [32-1:0] k3_o;
  logic k3_wr_o;
  logic [32-1:0] center_x_o;
  logic center_x_wr_o;
  logic [32-1:0] center_y_o;
  logic center_y_wr_o;
  logic [32-1:0] scale_o;
  logic scale_wr_o;
  logic bypass_o;
  logic bypass_wr_o;
  logic [32-1:0] interp_mode_o;
  logic interp_mode_wr_o;
  logic [32-1:0] calib_mode_o;
  logic calib_mode_wr_o;
  logic [32-1:0] fx_o;
  logic fx_wr_o;
  logic [32-1:0] fy_o;
  logic fy_wr_o;
  logic [32-1:0] cx_o;
  logic cx_wr_o;
  logic [32-1:0] cy_o;
  logic cy_wr_o;
  logic [32-1:0] p1_o;
  logic p1_wr_o;
  logic [32-1:0] p2_o;
  logic p2_wr_o;
  logic [32-1:0] model_sel_o;
  logic model_sel_wr_o;
  logic [32-1:0] h11_o;
  logic h11_wr_o;
  logic [32-1:0] h12_o;
  logic h12_wr_o;
  logic [32-1:0] h13_o;
  logic h13_wr_o;
  logic [32-1:0] h21_o;
  logic h21_wr_o;
  logic [32-1:0] h22_o;
  logic h22_wr_o;
  logic [32-1:0] h23_o;
  logic h23_wr_o;
  logic [32-1:0] h31_o;
  logic h31_wr_o;
  logic [32-1:0] h32_o;
  logic h32_wr_o;
  assign r.cfg_ctrl = ctrl_o;
  assign r.cfg_ctrl_wr = ctrl_wr_o;
  assign status_i = r.sts_status;
  assign r.cfg_status = status_o;
  assign r.cfg_status_wr = status_wr_o;
  assign r.cfg_img_width = img_width_o;
  assign r.cfg_img_width_wr = img_width_wr_o;
  assign r.cfg_img_height = img_height_o;
  assign r.cfg_img_height_wr = img_height_wr_o;
  assign r.cfg_k1 = k1_o;
  assign r.cfg_k1_wr = k1_wr_o;
  assign r.cfg_k2 = k2_o;
  assign r.cfg_k2_wr = k2_wr_o;
  assign r.cfg_k3 = k3_o;
  assign r.cfg_k3_wr = k3_wr_o;
  assign r.cfg_center_x = center_x_o;
  assign r.cfg_center_x_wr = center_x_wr_o;
  assign r.cfg_center_y = center_y_o;
  assign r.cfg_center_y_wr = center_y_wr_o;
  assign r.cfg_scale = scale_o;
  assign r.cfg_scale_wr = scale_wr_o;
  assign r.cfg_bypass = bypass_o;
  assign r.cfg_bypass_wr = bypass_wr_o;
  assign r.cfg_interp_mode = interp_mode_o;
  assign r.cfg_interp_mode_wr = interp_mode_wr_o;
  assign r.cfg_calib_mode = calib_mode_o;
  assign r.cfg_calib_mode_wr = calib_mode_wr_o;
  assign r.cfg_fx = fx_o;
  assign r.cfg_fx_wr = fx_wr_o;
  assign r.cfg_fy = fy_o;
  assign r.cfg_fy_wr = fy_wr_o;
  assign r.cfg_cx = cx_o;
  assign r.cfg_cx_wr = cx_wr_o;
  assign r.cfg_cy = cy_o;
  assign r.cfg_cy_wr = cy_wr_o;
  assign r.cfg_p1 = p1_o;
  assign r.cfg_p1_wr = p1_wr_o;
  assign r.cfg_p2 = p2_o;
  assign r.cfg_p2_wr = p2_wr_o;
  assign r.cfg_model_sel = model_sel_o;
  assign r.cfg_model_sel_wr = model_sel_wr_o;
  assign r.cfg_h11 = h11_o;
  assign r.cfg_h11_wr = h11_wr_o;
  assign r.cfg_h12 = h12_o;
  assign r.cfg_h12_wr = h12_wr_o;
  assign r.cfg_h13 = h13_o;
  assign r.cfg_h13_wr = h13_wr_o;
  assign r.cfg_h21 = h21_o;
  assign r.cfg_h21_wr = h21_wr_o;
  assign r.cfg_h22 = h22_o;
  assign r.cfg_h22_wr = h22_wr_o;
  assign r.cfg_h23 = h23_o;
  assign r.cfg_h23_wr = h23_wr_o;
  assign r.cfg_h31 = h31_o;
  assign r.cfg_h31_wr = h31_wr_o;
  assign r.cfg_h32 = h32_o;
  assign r.cfg_h32_wr = h32_wr_o;
  // ---------------- register map
  localparam logic [31:0] IP_ID      = "VSYS";
  localparam logic [31:0] IP_VERSION = "1.10";
  localparam logic [31:0] IP_DATE    = 32'h10122026;   // mm/dd/yyyy, BCD
  localparam logic [7:0] A_ID = 8'h0, A_VERSION = 8'h4, A_DATE = 8'h8;
  localparam logic [7:0] A_CTRL = 8'h10;
  localparam logic [7:0] A_STATUS = 8'h14;
  localparam logic [7:0] A_IMG_WIDTH = 8'h18;
  localparam logic [7:0] A_IMG_HEIGHT = 8'h1C;
  localparam logic [7:0] A_K1 = 8'h20;
  localparam logic [7:0] A_K2 = 8'h24;
  localparam logic [7:0] A_K3 = 8'h28;
  localparam logic [7:0] A_CENTER_X = 8'h2C;
  localparam logic [7:0] A_CENTER_Y = 8'h30;
  localparam logic [7:0] A_SCALE = 8'h34;
  localparam logic [7:0] A_BYPASS = 8'h38;
  localparam logic [7:0] A_INTERP_MODE = 8'h3C;
  localparam logic [7:0] A_CALIB_MODE = 8'h40;
  localparam logic [7:0] A_FX = 8'h44;
  localparam logic [7:0] A_FY = 8'h48;
  localparam logic [7:0] A_CX = 8'h4C;
  localparam logic [7:0] A_CY = 8'h50;
  localparam logic [7:0] A_P1 = 8'h54;
  localparam logic [7:0] A_P2 = 8'h58;
  localparam logic [7:0] A_MODEL_SEL = 8'h5C;
  localparam logic [7:0] A_H11 = 8'h60;
  localparam logic [7:0] A_H12 = 8'h64;
  localparam logic [7:0] A_H13 = 8'h68;
  localparam logic [7:0] A_H21 = 8'h6C;
  localparam logic [7:0] A_H22 = 8'h70;
  localparam logic [7:0] A_H23 = 8'h74;
  localparam logic [7:0] A_H31 = 8'h78;
  localparam logic [7:0] A_H32 = 8'h7C;
  localparam int MAP_WORDS = 32;

  logic             wr_en, rd_en, wr_err_q;
  logic [7:0]       wr_addr, rd_addr, rd_addr_q;
  wire unused_addr_lsbs = &{1'b0, wr_addr[1:0], rd_addr[1:0]};   // word access: the byte offset is not decoded
  logic [31:0]      wr_data, rd_data;
  logic [3:0]       wr_strb;
  regbus_if #(.ADDR_W(8)) bus ();               // register bus of the AXI4-Lite front end
  assign wr_en = bus.wr;
  assign wr_addr = bus.waddr;
  assign wr_data = bus.wdata;
  assign wr_strb = bus.wstrb;
  assign rd_en = bus.rd;
  assign rd_addr = bus.raddr;
  assign bus.wr_err = wr_err_q;
  assign bus.rdata = rd_data;
  assign bus.rd_valid = 1'b1;
  assign bus.rd_err = 1'b0;
  axi4_lite_slave #(
    .ADDR_W(8),
    .READ_WAIT(0),
    .MAP_WORDS(MAP_WORDS)
  ) u_axil (
    .aclk(clk),
    .aresetn(rst_n),
    .s_axil(s_axil),
    .bus(bus)
  );
  wire [7:0] wa = {wr_addr[7:2], 2'b00};
  // byte strobes applied to the written word
  logic [31:0] wmask;
  always_comb for (int b = 0; b < 4; b++) wmask[b*8 +: 8] = {8{wr_strb[b]}};

  // ---------------- writes
  logic [31:0] ctrl_q;
  logic [31:0] status_q;
  logic [31:0] img_width_q;
  logic [31:0] img_height_q;
  logic [31:0] k1_q;
  logic [31:0] k2_q;
  logic [31:0] k3_q;
  logic [31:0] center_x_q;
  logic [31:0] center_y_q;
  logic [31:0] scale_q;
  logic [31:0] bypass_q;
  logic [31:0] interp_mode_q;
  logic [31:0] calib_mode_q;
  logic [31:0] fx_q;
  logic [31:0] fy_q;
  logic [31:0] cx_q;
  logic [31:0] cy_q;
  logic [31:0] p1_q;
  logic [31:0] p2_q;
  logic [31:0] model_sel_q;
  logic [31:0] h11_q;
  logic [31:0] h12_q;
  logic [31:0] h13_q;
  logic [31:0] h21_q;
  logic [31:0] h22_q;
  logic [31:0] h23_q;
  logic [31:0] h31_q;
  logic [31:0] h32_q;
  always_ff @(posedge clk) begin
    if (!rst_n) begin
      ctrl_q <= '0;
      ctrl_wr_o <= 1'b0;
      status_q <= '0;
      status_wr_o <= 1'b0;
      img_width_q <= 32'h40;
      img_width_wr_o <= 1'b0;
      img_height_q <= 32'h40;
      img_height_wr_o <= 1'b0;
      k1_q <= 32'h0;
      k1_wr_o <= 1'b0;
      k2_q <= 32'h0;
      k2_wr_o <= 1'b0;
      k3_q <= 32'h0;
      k3_wr_o <= 1'b0;
      center_x_q <= 32'h8000;
      center_x_wr_o <= 1'b0;
      center_y_q <= 32'h8000;
      center_y_wr_o <= 1'b0;
      scale_q <= 32'h10000;
      scale_wr_o <= 1'b0;
      bypass_q <= 32'h1;
      bypass_wr_o <= 1'b0;
      interp_mode_q <= 32'h0;
      interp_mode_wr_o <= 1'b0;
      calib_mode_q <= 32'h0;
      calib_mode_wr_o <= 1'b0;
      fx_q <= 32'h10000;
      fx_wr_o <= 1'b0;
      fy_q <= 32'h10000;
      fy_wr_o <= 1'b0;
      cx_q <= 32'h0;
      cx_wr_o <= 1'b0;
      cy_q <= 32'h0;
      cy_wr_o <= 1'b0;
      p1_q <= 32'h0;
      p1_wr_o <= 1'b0;
      p2_q <= 32'h0;
      p2_wr_o <= 1'b0;
      model_sel_q <= 32'h0;
      model_sel_wr_o <= 1'b0;
      h11_q <= 32'h10000;
      h11_wr_o <= 1'b0;
      h12_q <= 32'h0;
      h12_wr_o <= 1'b0;
      h13_q <= 32'h0;
      h13_wr_o <= 1'b0;
      h21_q <= 32'h0;
      h21_wr_o <= 1'b0;
      h22_q <= 32'h10000;
      h22_wr_o <= 1'b0;
      h23_q <= 32'h0;
      h23_wr_o <= 1'b0;
      h31_q <= 32'h0;
      h31_wr_o <= 1'b0;
      h32_q <= 32'h0;
      h32_wr_o <= 1'b0;
      wr_err_q <= 1'b0;
    end else begin
      wr_err_q <= wr_en && (wa == A_ID || wa == A_VERSION || wa == A_DATE);   // writes to read-only words: SLVERR
      begin
        ctrl_wr_o <= wr_en && wa == A_CTRL;
        if (wr_en && wa == A_CTRL) ctrl_q <= (ctrl_q & ~wmask) | (wr_data & wmask);
      end
      begin
        status_wr_o <= wr_en && wa == A_STATUS;
        if (wr_en && wa == A_STATUS) status_q <= (status_q & ~wmask) | (wr_data & wmask);
      end
      begin
        img_width_wr_o <= wr_en && wa == A_IMG_WIDTH;
        if (wr_en && wa == A_IMG_WIDTH) img_width_q <= (img_width_q & ~wmask) | (wr_data & wmask);
      end
      begin
        img_height_wr_o <= wr_en && wa == A_IMG_HEIGHT;
        if (wr_en && wa == A_IMG_HEIGHT) img_height_q <= (img_height_q & ~wmask) | (wr_data & wmask);
      end
      begin
        k1_wr_o <= wr_en && wa == A_K1;
        if (wr_en && wa == A_K1) k1_q <= (k1_q & ~wmask) | (wr_data & wmask);
      end
      begin
        k2_wr_o <= wr_en && wa == A_K2;
        if (wr_en && wa == A_K2) k2_q <= (k2_q & ~wmask) | (wr_data & wmask);
      end
      begin
        k3_wr_o <= wr_en && wa == A_K3;
        if (wr_en && wa == A_K3) k3_q <= (k3_q & ~wmask) | (wr_data & wmask);
      end
      begin
        center_x_wr_o <= wr_en && wa == A_CENTER_X;
        if (wr_en && wa == A_CENTER_X) center_x_q <= (center_x_q & ~wmask) | (wr_data & wmask);
      end
      begin
        center_y_wr_o <= wr_en && wa == A_CENTER_Y;
        if (wr_en && wa == A_CENTER_Y) center_y_q <= (center_y_q & ~wmask) | (wr_data & wmask);
      end
      begin
        scale_wr_o <= wr_en && wa == A_SCALE;
        if (wr_en && wa == A_SCALE) scale_q <= (scale_q & ~wmask) | (wr_data & wmask);
      end
      begin
        bypass_wr_o <= wr_en && wa == A_BYPASS;
        if (wr_en && wa == A_BYPASS) bypass_q <= (bypass_q & ~wmask) | (wr_data & wmask);
      end
      begin
        interp_mode_wr_o <= wr_en && wa == A_INTERP_MODE;
        if (wr_en && wa == A_INTERP_MODE) interp_mode_q <= (interp_mode_q & ~wmask) | (wr_data & wmask);
      end
      begin
        calib_mode_wr_o <= wr_en && wa == A_CALIB_MODE;
        if (wr_en && wa == A_CALIB_MODE) calib_mode_q <= (calib_mode_q & ~wmask) | (wr_data & wmask);
      end
      begin
        fx_wr_o <= wr_en && wa == A_FX;
        if (wr_en && wa == A_FX) fx_q <= (fx_q & ~wmask) | (wr_data & wmask);
      end
      begin
        fy_wr_o <= wr_en && wa == A_FY;
        if (wr_en && wa == A_FY) fy_q <= (fy_q & ~wmask) | (wr_data & wmask);
      end
      begin
        cx_wr_o <= wr_en && wa == A_CX;
        if (wr_en && wa == A_CX) cx_q <= (cx_q & ~wmask) | (wr_data & wmask);
      end
      begin
        cy_wr_o <= wr_en && wa == A_CY;
        if (wr_en && wa == A_CY) cy_q <= (cy_q & ~wmask) | (wr_data & wmask);
      end
      begin
        p1_wr_o <= wr_en && wa == A_P1;
        if (wr_en && wa == A_P1) p1_q <= (p1_q & ~wmask) | (wr_data & wmask);
      end
      begin
        p2_wr_o <= wr_en && wa == A_P2;
        if (wr_en && wa == A_P2) p2_q <= (p2_q & ~wmask) | (wr_data & wmask);
      end
      begin
        model_sel_wr_o <= wr_en && wa == A_MODEL_SEL;
        if (wr_en && wa == A_MODEL_SEL) model_sel_q <= (model_sel_q & ~wmask) | (wr_data & wmask);
      end
      begin
        h11_wr_o <= wr_en && wa == A_H11;
        if (wr_en && wa == A_H11) h11_q <= (h11_q & ~wmask) | (wr_data & wmask);
      end
      begin
        h12_wr_o <= wr_en && wa == A_H12;
        if (wr_en && wa == A_H12) h12_q <= (h12_q & ~wmask) | (wr_data & wmask);
      end
      begin
        h13_wr_o <= wr_en && wa == A_H13;
        if (wr_en && wa == A_H13) h13_q <= (h13_q & ~wmask) | (wr_data & wmask);
      end
      begin
        h21_wr_o <= wr_en && wa == A_H21;
        if (wr_en && wa == A_H21) h21_q <= (h21_q & ~wmask) | (wr_data & wmask);
      end
      begin
        h22_wr_o <= wr_en && wa == A_H22;
        if (wr_en && wa == A_H22) h22_q <= (h22_q & ~wmask) | (wr_data & wmask);
      end
      begin
        h23_wr_o <= wr_en && wa == A_H23;
        if (wr_en && wa == A_H23) h23_q <= (h23_q & ~wmask) | (wr_data & wmask);
      end
      begin
        h31_wr_o <= wr_en && wa == A_H31;
        if (wr_en && wa == A_H31) h31_q <= (h31_q & ~wmask) | (wr_data & wmask);
      end
      begin
        h32_wr_o <= wr_en && wa == A_H32;
        if (wr_en && wa == A_H32) h32_q <= (h32_q & ~wmask) | (wr_data & wmask);
      end
    end
  end
  assign ctrl_o = ctrl_q[1-1:0];
  assign status_o = status_q[3-1:0];
  assign img_width_o = img_width_q[32-1:0];
  assign img_height_o = img_height_q[32-1:0];
  assign k1_o = k1_q[32-1:0];
  assign k2_o = k2_q[32-1:0];
  assign k3_o = k3_q[32-1:0];
  assign center_x_o = center_x_q[32-1:0];
  assign center_y_o = center_y_q[32-1:0];
  assign scale_o = scale_q[32-1:0];
  assign bypass_o = bypass_q[1-1:0];
  assign interp_mode_o = interp_mode_q[32-1:0];
  assign calib_mode_o = calib_mode_q[32-1:0];
  assign fx_o = fx_q[32-1:0];
  assign fy_o = fy_q[32-1:0];
  assign cx_o = cx_q[32-1:0];
  assign cy_o = cy_q[32-1:0];
  assign p1_o = p1_q[32-1:0];
  assign p2_o = p2_q[32-1:0];
  assign model_sel_o = model_sel_q[32-1:0];
  assign h11_o = h11_q[32-1:0];
  assign h12_o = h12_q[32-1:0];
  assign h13_o = h13_q[32-1:0];
  assign h21_o = h21_q[32-1:0];
  assign h22_o = h22_q[32-1:0];
  assign h23_o = h23_q[32-1:0];
  assign h31_o = h31_q[32-1:0];
  assign h32_o = h32_q[32-1:0];

  // ---------------- reads: the word addressed in the clock before
  always_ff @(posedge clk) if (rd_en) rd_addr_q <= {rd_addr[7:2], 2'b00};
  always_comb begin
    rd_data = '0;
    case (rd_addr_q)
      A_ID:      rd_data = IP_ID;
      A_VERSION: rd_data = IP_VERSION;
      A_DATE:    rd_data = IP_DATE;
      A_STATUS: rd_data = 32'(status_i);
      A_IMG_WIDTH: rd_data = 32'(img_width_q[32-1:0]);
      A_IMG_HEIGHT: rd_data = 32'(img_height_q[32-1:0]);
      A_K1: rd_data = 32'(k1_q[32-1:0]);
      A_K2: rd_data = 32'(k2_q[32-1:0]);
      A_K3: rd_data = 32'(k3_q[32-1:0]);
      A_CENTER_X: rd_data = 32'(center_x_q[32-1:0]);
      A_CENTER_Y: rd_data = 32'(center_y_q[32-1:0]);
      A_SCALE: rd_data = 32'(scale_q[32-1:0]);
      A_BYPASS: rd_data = 32'(bypass_q[1-1:0]);
      A_INTERP_MODE: rd_data = 32'(interp_mode_q[32-1:0]);
      A_CALIB_MODE: rd_data = 32'(calib_mode_q[32-1:0]);
      A_FX: rd_data = 32'(fx_q[32-1:0]);
      A_FY: rd_data = 32'(fy_q[32-1:0]);
      A_CX: rd_data = 32'(cx_q[32-1:0]);
      A_CY: rd_data = 32'(cy_q[32-1:0]);
      A_P1: rd_data = 32'(p1_q[32-1:0]);
      A_P2: rd_data = 32'(p2_q[32-1:0]);
      A_MODEL_SEL: rd_data = 32'(model_sel_q[32-1:0]);
      A_H11: rd_data = 32'(h11_q[32-1:0]);
      A_H12: rd_data = 32'(h12_q[32-1:0]);
      A_H13: rd_data = 32'(h13_q[32-1:0]);
      A_H21: rd_data = 32'(h21_q[32-1:0]);
      A_H22: rd_data = 32'(h22_q[32-1:0]);
      A_H23: rd_data = 32'(h23_q[32-1:0]);
      A_H31: rd_data = 32'(h31_q[32-1:0]);
      A_H32: rd_data = 32'(h32_q[32-1:0]);
      default: begin
      end
    endcase
  end
endmodule
